Input: {"question": "When was Bartholomew Green born?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0357-b0de1b628419:d00", "start": 0, "end": 163, "text": "Bartholomew Green (printer, born 1666) Bartholomew Green (October 12, 1666 – December 28, 1732) was a printer at and later the publisher of The Boston News-Letter."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0357-b0de1b628419:d00", "start": 164, "end": 204, "text": "He was born in Cambridge, Massachusetts."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0357-b0de1b628419:d00", "start": 205, "end": 311, "text": "The Boston News-Letter is regarded as the first continuously published newspaper in British North America."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0357-b0de1b628419:d00", "start": 312, "end": 403, "text": "Initially, it was heavily subsidized by the British government, with a limited circulation."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0357-b0de1b628419:d00", "start": 404, "end": 453, "text": "The News-Letter’s first editor was John Campbell."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0357-b0de1b628419:d00", "start": 454, "end": 514, "text": "In 1722 the editorship passed to Green, the paper’s printer."}, "D1S7": {"document_number": 1, "doc_id": "ramdocs-0357-b0de1b628419:d00", "start": 515, "end": 598, "text": "Green changed the focus of the newspaper to place more emphasis on domestic events."}, "D1S8": {"document_number": 1, "doc_id": "ramdocs-0357-b0de1b628419:d00", "start": 599, "end": 643, "text": "After his death in 1732 his son John Draper,"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0357-b0de1b628419:d01", "start": 0, "end": 162, "text": "Bartholomew Green (printer, born 1700) Bartholomew Green (January 1, 1700 – December 28, 1732) was a printer at and later the publisher of The Boston News-Letter."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0357-b0de1b628419:d01", "start": 163, "end": 203, "text": "He was born in Cambridge, Massachusetts."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0357-b0de1b628419:d01", "start": 204, "end": 310, "text": "The Boston News-Letter is regarded as the first continuously published newspaper in British North America."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0357-b0de1b628419:d01", "start": 311, "end": 402, "text": "Initially, it was heavily subsidized by the British government, with a limited circulation."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0357-b0de1b628419:d01", "start": 403, "end": 452, "text": "The News-Letter’s first editor was John Campbell."}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0357-b0de1b628419:d01", "start": 453, "end": 513, "text": "In 1722 the editorship passed to Green, the paper’s printer."}, "D2S7": {"document_number": 2, "doc_id": "ramdocs-0357-b0de1b628419:d01", "start": 514, "end": 597, "text": "Green changed the focus of the newspaper to place more emphasis on domestic events."}, "D2S8": {"document_number": 2, "doc_id": "ramdocs-0357-b0de1b628419:d01", "start": 598, "end": 642, "text": "After his death in 1732 his son John Draper,"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0357-b0de1b628419:d02", "start": 0, "end": 60, "text": "Bartholomew Green (printer, born 1699) Bartholomew Green Jr."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0357-b0de1b628419:d02", "start": 61, "end": 163, "text": "(1699 or 1701 – October 29, 1751) was a son of Bartholomew Green, printer of the \"Boston News-Letter\"."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0357-b0de1b628419:d02", "start": 164, "end": 228, "text": "Green married Hannah Hammond in 1724 and they had five children."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0357-b0de1b628419:d02", "start": 229, "end": 293, "text": "He apprenticed with his father until he went on his own in 1725."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0357-b0de1b628419:d02", "start": 294, "end": 407, "text": "Almost immediately he began printing the \"Boston Gazette\" which was a rival to his father's \"Boston News-Letter\"."}, "D3S6": {"document_number": 3, "doc_id": "ramdocs-0357-b0de1b628419:d02", "start": 408, "end": 456, "text": "He continued to print this newspaper until 1732."}, "D3S7": {"document_number": 3, "doc_id": "ramdocs-0357-b0de1b628419:d02", "start": 457, "end": 567, "text": "He also worked with the firm of Bushell, Allen and Green and developed a reputation for high quality printing."}, "D3S8": {"document_number": 3, "doc_id": "ramdocs-0357-b0de1b628419:d02", "start": 568, "end": 600, "text": "A commission in the British army"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0357-b0de1b628419:d03", "start": 0, "end": 102, "text": "Bartholomew Green (martyr) Bartholomew or Bartlet Green (1530–1556), was an English Protestant martyr."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0357-b0de1b628419:d03", "start": 103, "end": 162, "text": "Green was born in the parish of Basinghall, city of London."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0357-b0de1b628419:d03", "start": 163, "end": 319, "text": "He was of a wealthy Roman Catholic family, and at the age of sixteen was sent by his parents, 'who favoured learning,' to Oxford University, proceeding B.A."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0357-b0de1b628419:d03", "start": 320, "end": 328, "text": "in 1547."}, "D4S5": {"document_number": 4, "doc_id": "ramdocs-0357-b0de1b628419:d03", "start": 329, "end": 447, "text": "At the university he was a laborious student, and was converted by Peter Martyr's lectures to the Protestant religion."}, "D4S6": {"document_number": 4, "doc_id": "ramdocs-0357-b0de1b628419:d03", "start": 448, "end": 603, "text": "On leaving Oxford Green entered the Inner Temple, and after a period of dissipation his earlier impressions revived, and he gave up his worldly amusements."}, "D4S7": {"document_number": 4, "doc_id": "ramdocs-0357-b0de1b628419:d03", "start": 604, "end": 619, "text": "His family were"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0357-b0de1b628419:d04", "start": 0, "end": 589, "text": "information Cite this page Get shortened URL Download QR code Print/export Download as PDF Printable version In other projects Wikidata item Appearance move to sidebar hide From Wikipedia , the free encyclopedia Bartholomew Green may refer to : Bartholomew Green ( martyr ) ( 1530–1556 ) , English Protestant martyr Bartholomew Green ( printer , born 1666 ) , American printer and publisher Bartholomew Green ( printer , born 1699 ) ( 1699–1751 ) , son of Bartholomew Green , printer of the Boston News-Letter Bartholomew Green , Essex , a hamlet in Felsted , England Topics referred to by"}}, "original_cards": [{"doc_id": "ramdocs-0357-b0de1b628419:d00", "card_id": "ramdocs-0357-b0de1b628419:d00:c0", "entity": "Bartholomew Green", "scope": "birth date", "claim": "Bartholomew Green was born on October 12, 1666.", "answer": "October 12, 1666", "quote": "Bartholomew Green (printer, born 1666) Bartholomew Green (October 12, 1666 – December 28, 1732) was a printer at and later the publisher of The Boston News-Letter.", "original_document_number": 1}, {"doc_id": "ramdocs-0357-b0de1b628419:d01", "card_id": "ramdocs-0357-b0de1b628419:d01:c0", "entity": "Bartholomew Green", "scope": "birth date", "claim": "Bartholomew Green was born on January 1, 1700.", "answer": "January 1, 1700", "quote": "Bartholomew Green (printer, born 1700) Bartholomew Green (January 1, 1700 – December 28, 1732) was a printer at and later the publisher of The Boston News-Letter.", "original_document_number": 2}, {"doc_id": "ramdocs-0357-b0de1b628419:d02", "card_id": "ramdocs-0357-b0de1b628419:d02:c0", "entity": "Bartholomew Green", "scope": "birth year", "claim": "Bartholomew Green was born in 1699.", "answer": "1699", "quote": "Bartholomew Green (printer, born 1699) Bartholomew Green Jr.", "original_document_number": 3}, {"doc_id": "ramdocs-